item.command:
/bin/bash -lc 'for z in inputs/scogs_animals.zip inputs/scogs_fungi.zip; do
  echo "$z"
  unzip -Z1 "$z" | sed '"'s/.*//' | awk '
    /\\.treefile"'$/ {t++}
    /'"\\.iqtree"'$/ {i++}
    /'"\\.faa\\.mafft\\.clipkit"'$/ {a++}
    END {print "treefiles",t,"iqtree",i,"trimmed_alignments",a}'"'
done
python - <<'PY'
try:
 import Bio
 print('Biopython', Bio.__version__)
except Exception as e: print('No Biopython', e)
PY
unzip -Z1 inputs/scogs_animals.zip | awk '/\\.treefile"'$/{print; if(++n==5) exit}'"' | while read f; do echo \""'$f"; unzip -p inputs/scogs_animals.zip "$f"; done
unzip -Z1 inputs/scogs_fungi.zip | awk '"'/\\.treefile"'$/{print; if(++n==5) exit}'"' | while read f; do echo \""'$f"; unzip -p inputs/scogs_fungi.zip "$f"; done'

